<template>
    <div class="layout-px-spacing">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>work Orders</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>

            <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button v-if="user_permissions.includes('can_create_work_order')" class="btn btn-primary " @click="work_order_registration =! work_order_registration">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>  

                    <!-- loading spinner starts -->
                 <div v-if="loading_spinner" v-html="loadingIndicator()"></div>
        <!-- Loading spinner ends -->
 <!-- item registration form starts -->
 <form v-if="work_order_registration" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="submitWorkOrder()">
        <h4 class="text-center">WORK ORDER REGISTRATION FORM</h4>
        <div class="row mb-2">
    
            <div class="col-md-3">
                <label class="form-label">Project</label>
                <Multiselect
  v-model="project"
  :options="projects"
  :close-on-select="true"
  label="name"
  value-prop="id"
  placeholder="Select Project"  
  :searchable="true" 
/>             </div>

 <div class="col-md-3">
                <label class="form-label">Order For</label>
                <Multiselect
  v-model="workOrderGroup"
  :options="workOrderGroups"
  :close-on-select="true"
  label="description"
  value-prop="id"
  placeholder="Select Group"  
  :searchable="true" 
/>             </div>

            <div class="col-md-6">
                <label class="form-label">Description</label>
                <input type="text" class="form-control" placeholder="Enter Description" v-model="description" required>
            </div>

            <div class="mt-3">
              <h5>Items Required</h5>
                <div class="row">
                  <div class="col-md-4">
                        <label class="form-label">Item</label>
                        <input type="text" class="form-control" placeholder="Enter Item" v-model="item" required>
                  </div>
                  <div class="col-md-4">
                       <label class="form-label">Quantity</label>
                        <input type="number" step="any" class="form-control" placeholder="Enter Qty" v-model="quantity" required>
                  </div>
                     <div class="col-md-3">
                       <label class="form-label">Unit</label>
                <Multiselect
  v-model="unit"
  :options="units"
  :close-on-select="true"
  label="short_name"
  value-prop="id"
  placeholder="Select Unit"  
  :searchable="true" 
/>                   </div>

                     <div class="col-md-1">
                       <label class="form-label">Add</label><br/>
 <button type="button" class="btn btn-success px-2 py-2" @click="pushItem()">
<i class="bi bi-plus-square"></i>  
</button>                </div>

                </div>
            </div>

                    <div 
        v-if="orderItems.length>0"
        class="row mb-3">
        <div class="col-12">
          <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
            <div class="custom-table table3">
                <v-client-table 
                    :data="orderItems" 
                    :columns="orderItemColumns" 
                    :options="table_option"
                >
                    <template #actions="props">
                        <a href="javascript:void(0);" title="Delete" @click="pullOrderItem(props.row.Sno)">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" class="bi bi-trash text-danger" viewBox="0 0 16 16">
                                <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                                <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1z"/>
                            </svg>
                        </a>
                    </template>
                </v-client-table>
            </div>
            </div>
            </div>
        </div>
    </div>


        </div>
        <div class="text-end gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="work_order_registration = false; resetForm();">Cancel</button>
            <button type="submit" class="btn btn-primary">Register</button>
        </div>
    </form>
             <!-- item registration form ends-->
      
        <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="work_orders" :columns="columns" :options="table_option">
                           
                            <template #actions="props">
                                
                                    <a href="javascript:;" 
                                       v-if="user_permissions.includes('can_edit_work_order')"
                                    class="edit me-3" @click="edit_row(props.row)">
                                           <i class="bi bi-pencil-square fs-5 text-primary"></i>
                                        </a>

                                         <a href="javascript:;"
                                         data-bs-toggle="modal"
                                         data-bs-target="#preview"
                                         @click="selectedOrder = props.row"
                                         >
                                            <i class="bi bi-eye fs-4 text-primary me-2"></i>
                                         </a>

                                            <a href="javascript:;"
                                         data-bs-toggle="modal"
                                         data-bs-target="#fabrication"
                                         @click="selectedOrder = props.row"
                                         v-if="user_permissions.includes('can_create_fabrication')"
                                         >
                                            <i class="bi bi-hammer fs-4 text-dark"></i>
                                         </a>
                                        
                                        
                              
<!-- modal starts -->

 
                                
                            </template>
                           <template #footer>
                               <div class="modal-footer">
                                   <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
                                   <button type="button" class="btn btn-primary" @click="save_edit" :disabled="isSaving" >Save changes</button>
                               </div>
                           </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>


<!-- ===== work order modal -->
 <workOrderModal :workOrderId="selectedOrder.id"/>
 <!-- ==== work order modal -->

 <fabrication
  :workOrderId="selectedOrder.id" 
  :description="selectedOrder.description" 
  :project="selectedOrder.project"
  :date="selectedOrder.date"
  :issuer="selectedOrder.issuer"
  />




   </div>
</template>

<script setup>
    import { onMounted, ref,inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const user_permissions = JSON.parse(localStorage.getItem('user')).permissions

    import workOrderModal from './components/workOrderModal.vue';
    import fabrication from './components/fabrication.vue';
    const formatDate = inject('formatDate');
    const loadingIndicator = inject('loadingIndicator');
    const orderItemColumns = ref(['Sno', 'item','unit', 'quantity', 'actions']);
    const item = ref('')
    const quantity = ref('')
    const orderItems = ref([])
    const pushItem = ()=>{
      orderItems.value.push({
        Sno :  orderItems.value.length + 1,
        item : item.value,
        unit : unit.value.name,
        unit_id : unit.value.id,
        quantity : quantity.value
      }
      )
    }

     const pullOrderItem = (sno) => {
        orderItems.value = orderItems.value.filter(item => item.Sno !== sno);
        orderItems.value = orderItems.value.map((item, index) => ({
            ...item,
            Sno: index + 1
        }));
    };


    const editingRow = ref({});
    const name = ref('');
    const short_name = ref('');
    const status = ref('');
    const loading_spinner = ref(false);
    const columns = ref(['SNo','project', 'description', 'date', 'issuer', 'actions']);
    const work_orders = ref([]);
    const work_order_registration = ref(false);
    const table_option = ref({
        perPage: 10,
        perPageValues: [10, 20, 50],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const getWorkOrders = () => {
        loading_spinner.value = true;
        axiosInstance.get('/work-orders').then((response) => {
            
            work_orders.value = response.data.map((item, index) => {
                
                return {
                    ...item,
                    SNo: index + 1,
                    date: formatDate(item.date)
                };
            });
            
            loading_spinner.value = false;
        }).catch(error => {
            showError(error.message || "Failed to fetch work_orders");
            loading_spinner.value = false;
        });
    };


    const showMessage = inject('showMessage');
    const showError = inject('showError');





    const edit_row = (row) => {
        editingRow.value = { ...row }; 
        editModal.show();
    };

    const save_edit = async () => {
        editModal.hide();
        if (loading_spinner.value) return;
        try {
            
            loading_spinner.value = true;
            const response = await axiosInstance.put(`/work_orders/${editingRow.value.id}`, {
                name: editingRow.value.name,
                short_name: editingRow.value.short_name,
                status: editingRow.value.status
            });
            
            if (response.status === 200) {
                const index = work_orders.value.findIndex(item => item.id === editingRow.value.id);
                if (index !== -1) {
                    work_orders.value[index].name = editingRow.value.name;
                    work_orders.value[index].short_name = editingRow.value.short_name;
                    work_orders.value[index].status = editingRow.value.status;
                }
                showMessage('work_order updated successfully!');
            }
           
        } catch (error) {
            showError("Error updating work_order: " + (error.response?.data?.message || error.message));
        } finally {
            loading_spinner.value = false;
        }
      
    }; 


    const resetForm = () => {
    unit.value = '',
    description.value= '',
    project.value = ''
};

const projects = ref([])
const project = ref('')
const getProjects = async()=>{
  const response = await axiosInstance.get('get-projects')
  projects.value = response.data
}

const units = ref([])
const unit = ref('')
const getUnits = async()=>{
  const response = await axiosInstance.get('units')
  units.value = response.data
}



const workOrderGroup = ref('')
const workOrderGroups = ref([])
const getWorkOrderGroups = async()=>{
  const response = await axiosInstance.get('work-order-groups')
  workOrderGroups.value = response.data
}

const description = ref('')
const submitWorkOrder = async()=>{
    const payload = {
        order_group_id : workOrderGroup.value.id,
        description : description.value,
        issuer_id : JSON.parse(localStorage.getItem('user')).id,
        project_id : project.value.id,
        items : orderItems.value
    }


    try{
      const response = await axiosInstance.post('work-orders',payload)
      showMessage('Work Order Created!')
      getWorkOrders()
    }catch(error){
        console.log(error)
        showError(error.message)
    }
}



const selectedOrder = ref('')
    onMounted(() => {
         getProjects();
         getUnits();
         getWorkOrderGroups()
               getWorkOrders()

    });
</script>

