                  <div class="col-md-4">
                       <label class="form-label">Quantity</label>
                        <input type="number" step="any" class="form-control" placeholder="Enter Qty" v-model="produced_quantity" required>
                  </div>
                     <div class="col-md-3">
                       <label class="form-label">Unit</label>
                <Multiselect
